input.content:
/*
 * Standalone supplementary harness for the CVE port.
 *
 * This is NOT the kernel build. It replicates the exact guard expression that
 * ext4_init_block_bitmap() uses for the block bitmap / inode bitmap / inode
 * table sites:
 *      pre-fix :  if (!flex_bg || ext4_block_in_group(sb, tmp, block_group))
 *      post-fix:  if (ext4_block_in_group(sb, tmp, block_group))
 * and checks the positive (in-group) and negative (out-of-group, no FLEX_BG)
 * paths. It exits 0 only if the post-fix logic blocks the out-of-group write
 * while the pre-fix logic permits it.
 */
#include <stdio.h>
#include <string.h>

#define BITMAP_BYTES 1024
#define BITS (BITMAP_BYTES * 8)

static long group_first = 0;
static long blocks_per_group = 8192;

static unsigned char bitmap[BITS / 8];
static int out_of_bounds;

static int block_in_group(long block, long group)
{
	long actual = (block - group_first) / blocks_per_group;
	return actual == group;
}

static void set_bit(long index)
{
	if (index < 0 || index >= BITS) {
		out_of_bounds = 1;
		return;
	}
	bitmap[index / 8] |= (unsigned char)(1u << (index % 8));
}

/* Return 1 if a bit was written, 0 otherwise; also report OOB. */
static int run_case(int post_fix, int flex_bg, long tmp, long group, int *oob)
{
	long start = group_first + group * blocks_per_group;
	int guard;

	out_of_bounds = 0;
	memset(bitmap, 0, sizeof(bitmap));

	guard = post_fix ? block_in_group(tmp, group)
			 : (!flex_bg || block_in_group(tmp, group));
	if (guard)
		set_bit(tmp - start);

	*oob = out_of_bounds;
	return guard;
}

int main(void)
{
	int failures = 0;
	int oob, wrote;
	long group = 3;
	long start = group_first + group * blocks_per_group;

	/* Positive path: in-group block must be marked by both versions. */
	wrote = run_case(0, 0, start + 10, group, &oob);
	if (!wrote || oob) { printf("FAIL positive pre-fix\n"); failures++; }
	wrote = run_case(1, 0, start + 10, group, &oob);
	if (!wrote || oob) { printf("FAIL positive post-fix\n"); failures++; }

	/* Negative path: out-of-group block, no FLEX_BG.
	 * Pre-fix skips the check and writes an out-of-range bit.
	 * Post-fix must refuse and write nothing. */
	wrote = run_case(0, 0, 900000, group, &oob);
	printf("pre-fix  out-of-group flex_bg=0: wrote=%d out_of_bounds=%d\n", wrote, oob);
	if (!wrote || !oob) { printf("FAIL pre-fix did not reproduce OOB\n"); failures++; }
	wrote = run_case(1, 0, 900000, group, &oob);
	printf("post-fix out-of-group flex_bg=0: wrote=%d out_of_bounds=%d\n", wrote, oob);
	if (wrote || oob) { printf("FAIL post-fix still wrote OOB\n"); failures++; }

